    geo: null,
    titre: "Pierre Galet et l’ampélographie par la feuille",
    synth: "Pierre Galet (1921-2019), « père de l’ampélographie moderne », s’attaque d’abord aux porte-greffes, difficiles à reconnaître et sujets aux fraudes. Il codifie, avec Henri Agnel, un vocabulaire précis et privilégie les organes végétatifs (bourgeonnement, rameaux, et surtout la feuille adulte, vrai « visage » de la vigne), plus fiables que les grappes. Il reprend l’ampélométrie de Louis Ravaz : mesurer longueurs de nervures et angles de la feuille. L’OIV intègre ces descripteurs dans sa liste de 1983 (2e édition en 2009 avec des marqueurs biochimiques et génétiques, 3e édition adoptée en 2023), qui classe par exemple les feuilles selon leur nombre de lobes.",
    mnemo: "Galet lit la vigne comme un visage : la feuille, ses lobes, ses angles. On ne reconnaît pas quelqu’un à son panier (la grappe) mais à sa tête.",
    flash: { q: "Sur quoi repose l’ampélographie de Pierre Galet ?", a: "Sur les organes végétatifs, surtout la feuille adulte, et sur l’ampélométrie (mesure des nervures et de leurs angles, reprise de Ravaz).", keys: [["feuille","feuilles"],["ampélométrie","nervures","angles","mesure","mesures"]] },
    qcm: { q: "Par quoi Pierre Galet commence-t-il son travail d’identification ?", opts: ["Les cépages de cuve bourguignons", "Les porte-greffes", "Les raisins de table", "Les lambrusques"], good: 1, expl: "Les porte-greffes, nombreux et proches d’aspect, étaient difficiles à reconnaître et sujets aux fraudes : c’est là que le besoin d’identification était le plus pressant." },
    exos: [
      { type: "matching", prompt: "Associe chaque cépage à son nombre de lobes (exemples de Lepeltier, grille OIV).", payload: { pairs: [["Melon", "Feuille entière"], ["Chenin", "Trois lobes"], ["Riesling", "Cinq lobes"], ["Cabernet sauvignon", "Sept lobes"]] }, explanation: "La grille OIV classe les feuilles selon leur nombre de lobes ; c’est l’un des descripteurs que Galet a rendus systématiques." },
      { type: "mcq_multi", prompt: "Quels organes Galet juge-t-il les plus discriminants ?", payload: { options: ["La feuille", "Les rameaux", "Le bourgeonnement", "La grappe", "La baie"], answers: [0, 1, 2] }, explanation: "Pour Galet, les organes végétatifs sont plus fiables que les grappes, dont l’aspect varie davantage ; la feuille adulte est le vrai « visage » de la vigne." },
      { type: "short_answer", prompt: "Comment s’appelle la méthode qui mesure les nervures et les angles de la feuille ?", payload: { accepted: ["ampélométrie", "l’ampélométrie"] }, explanation: "Mise au point par Louis Ravaz et reprise par Galet, elle remplace l’impression visuelle par des mesures, plus faciles à comparer d’un observateur à l’autre." },
      { type: "true_false", prompt: "Vrai ou faux ?", payload: { statement: "La liste OIV des descripteurs de 2009 est toujours l’édition en vigueur.", answer: false }, explanation: "Une 3e édition a été adoptée en 2023 (résolution OIV-VITI 702-2023). Lepeltier cite celle de 2009." }
    ],
