    flash: { q: "Quels sont les six cépages interdits en France depuis 1934 ?", a: "Clinton, herbemont, isabelle, jacquez, noah, othello.", keys: [["clinton"],["herbemont"],["isabelle"],["jacquez"],["noah"],["othello"]] },
